/* Fleet recorder mic notice: the input's name, the live level strip and, when
 * the input carries no sound, a warning under them.
 *
 * VENDORED VERBATIM from project-scaffolding. Do NOT edit this file per-app:
 * nothing here varies between apps. Normalized from app-launcher's
 * `voice.js` / `voice-level.js` notice and voice-transcriber's `mic-notice.js`.
 *
 * Pairs with mic-notice.css and the vendored rec-wave, which reads the stream
 * the recorder already holds (no second getUserMedia, no new permission
 * prompt) and gives the silent verdict this module words. Exports:
 *   attachMicNotice(noticeEl, stream, opts) -> stop()   mount, watch, release
 *   inputLabel(stream), silentText(label)               the name and the words
 *   SILENT_MS                                           the 3000 ms window
 */

'use strict';

import { attachRecWave } from '../rec-wave/rec-wave.js';

// How long a take may carry no sound before it is flagged. iOS routes the mic
// to a Bluetooth headset that can carry nothing, and the strip stays flat.
export const SILENT_MS = 3000;

const STRIP_HEIGHT = 20;

const SILENT_DEFAULT = 'No sound from the microphone — check Bluetooth/AirPods';
const SILENT_REMOTE =
  'No sound from the microphone — check the Remote Desktop audio recording setting ' +
  "('Record from this computer')";

/**
 * The name the browser gives the live input ("AirPods", "iPhone Microphone"),
 * or '' when it withholds the label.
 *
 * @param {MediaStream} stream
 * @returns {string}
 */
export function inputLabel(stream) {
  try {
    const tracks = stream && stream.getAudioTracks ? stream.getAudioTracks() : [];
    return (tracks[0] && tracks[0].label) || '';
  } catch (_) {
    return '';
  }
}

/**
 * The warning for a silent input. Windows names the redirected Remote Desktop
 * input "Remote Audio"; a flat strip there is the RDP client's recording
 * setting, not a Bluetooth headset.
 *
 * @param {string} label  the input's name, '' when unknown.
 * @returns {string}
 */
export function silentText(label) {
  return /remote audio/i.test(label || '') ? SILENT_REMOTE : SILENT_DEFAULT;
}

function part(className) {
  const el = document.createElement('div');
  el.className = className;
  return el;
}

/**
 * Show the take's notice in `noticeEl` and flag a dead input within seconds.
 * The component builds the notice's contents (input line, level strip, warning)
 * and unhides `noticeEl`; the strip runs for the whole take, so the notice
 * shows even when the browser withholds the input's name.
 *
 * Call it in the same tap that starts recording. `stop()` empties and hides the
 * notice and releases the strip; it never stops the stream's tracks and is safe
 * to call more than once.
 *
 * @param {HTMLElement} noticeEl  an empty container, `hidden` at rest.
 * @param {MediaStream} stream  the stream the recorder already has.
 * @param {object} [opts]
 * @param {object} [opts.source]  a `createLevelSource()` the caller owns (to
 *        build it inside the tap on iOS); it is not closed on stop.
 * @param {boolean} [opts.timer=true]  show rec-wave's elapsed m:ss.
 * @param {(text: string, label: string) => void} [opts.onSilent]  the warning
 *        just showed; for a haptic, a toast or a log line.
 * @param {() => void} [opts.onSignal]  sound was heard and the warning cleared.
 * @returns {() => void} stop()
 */
export function attachMicNotice(noticeEl, stream, opts) {
  const o = opts || {};
  const label = inputLabel(stream);
  const text = silentText(label);

  const input = part('mic-notice-input');
  input.textContent = label ? 'Mic: ' + label : '';
  input.hidden = !label;
  const wave = part('mic-notice-wave');
  const warning = part('mic-notice-silent');
  warning.setAttribute('role', 'status');
  warning.hidden = true;

  noticeEl.textContent = '';
  noticeEl.classList.add('mic-notice');
  noticeEl.classList.remove('is-silent');
  noticeEl.append(input, wave, warning);
  noticeEl.hidden = false;

  // The warning's text is set when it shows, so a status region announces it.
  function setSilent(silent) {
    warning.textContent = silent ? text : '';
    warning.hidden = !silent;
    noticeEl.classList.toggle('is-silent', silent);
  }

  const stopWave = attachRecWave(wave, stream, {
    source: o.source,
    silenceMs: SILENT_MS,
    height: STRIP_HEIGHT,
    timer: o.timer !== false,
    onSilent() {
      setSilent(true);
      if (o.onSilent) o.onSilent(text, label);
    },
    onSignal() {
      setSilent(false);
      if (o.onSignal) o.onSignal();
    },
  });

  let stopped = false;
  return function stop() {
    if (stopped) return;
    stopped = true;
    stopWave();
    noticeEl.textContent = '';
    noticeEl.classList.remove('is-silent');
    noticeEl.hidden = true;
  };
}
